import{_ as a,W as o,N as s,k as n,h as t,o as i,p as d,n as l}from"./chunks/framework.CP1bd6yz.js";const b=JSON.parse('{"title":"Field Type","description":"","frontmatter":{},"headers":[],"relativePath":"guide/field-type.md","filePath":"guide/field-type.md"}'),h={name:"guide/field-type.md"},c={id:"field-type",tabindex:"-1"};function g(f,e,u,m,y,p){const r=o("Badge");return s(),n("div",null,[t("h1",c,[e[0]||(e[0]=i("Field Type ",-1)),d(r,{type:"warning",text:"beta"}),e[1]||(e[1]=i()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#field-type","aria-label":"Permalink to “Field Type”"},"​",-1))]),e[3]||(e[3]=l('<p>Order Lifecycle adds one custom field type - <strong>Order Lifecycle Events</strong> - that you attach to your Commerce order field layout. This page covers the field itself: where it goes, what it shows, and how it behaves. For the detail inside each section, see <a href="/order-lifecycle/guide/timeline-view.html">Timeline View</a>, <a href="/order-lifecycle/guide/statistics.html">Statistics</a>, and <a href="/order-lifecycle/guide/ai-insights.html">AI Insights</a>.</p><h2 id="adding-to-your-order-layout" tabindex="-1">Adding to Your Order Layout <a class="header-anchor" href="#adding-to-your-order-layout" aria-label="Permalink to “Adding to Your Order Layout”">​</a></h2><ol><li>Go to <strong>Settings</strong> → <strong>Fields</strong> → <strong>New Field</strong></li><li>Give it a name, e.g. &quot;Order Lifecycle&quot;</li><li>Set the field type to <strong>Order Lifecycle Events</strong></li><li>Save the field</li></ol><ol start="5"><li>Go to <strong>Commerce</strong> → <strong>System Settings</strong> → <strong>Order Field Layout</strong></li><li>Drag the field into your layout (a dedicated &quot;Logs&quot; or &quot;History&quot; tab keeps it out of the way of order editing)</li><li>Save the layout</li></ol><p>There&#39;s nothing to configure on the field itself - see <a href="#field-settings">Field Settings</a> below.</p><h2 id="what-it-shows" tabindex="-1">What It Shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to “What It Shows”">​</a></h2><p>The field renders up to three sections, top to bottom, depending on your plugin settings and whether the order has any recorded activity:</p><table tabindex="0"><thead><tr><th>Section</th><th>Shown when</th><th>Full detail</th></tr></thead><tbody><tr><td><strong>Summary cards</strong></td><td><a href="/order-lifecycle/guide/configuration.html#display"><code>showLifecycleStats</code></a> is enabled and the order has at least one event</td><td><a href="/order-lifecycle/guide/timeline-view.html#summary-cards">Timeline View → Summary Cards</a> / <a href="/order-lifecycle/guide/statistics.html#per-order-summary-cards">Statistics</a></td></tr><tr><td><strong>Order analysis</strong></td><td>An <a href="/order-lifecycle/guide/configuration.html#integrations">Anthropic API key</a> is configured</td><td><a href="/order-lifecycle/guide/ai-insights.html#per-order-insights">AI Insights → Per-Order Insights</a></td></tr><tr><td><strong>Event timeline</strong></td><td>The order has at least one recorded event</td><td><a href="/order-lifecycle/guide/timeline-view.html">Timeline View</a></td></tr></tbody></table><h2 id="field-settings" tabindex="-1">Field Settings <a class="header-anchor" href="#field-settings" aria-label="Permalink to “Field Settings”">​</a></h2><p>The field has <strong>no settings of its own</strong> - there&#39;s nothing to configure in the field&#39;s own settings screen when you add it to a layout. Everything that changes what the field shows or how it behaves lives in the plugin&#39;s own settings at <strong>Settings → Order Lifecycle</strong> instead (event logging toggles, the stats widget toggle, the Anthropic API key, and so on) - see <a href="/order-lifecycle/guide/configuration.html">Configuration</a> for the full list.</p><h2 id="requirements-restrictions" tabindex="-1">Requirements &amp; Restrictions <a class="header-anchor" href="#requirements-restrictions" aria-label="Permalink to “Requirements &amp; Restrictions”">​</a></h2><ul><li><strong>Craft Commerce order elements only.</strong> The field renders a warning note if it&#39;s added to a field layout for anything other than a Commerce <code>Order</code> element (a product type, an entry type, and so on).</li><li><strong>Read-only.</strong> The field doesn&#39;t store or accept any input - it has no content column (<code>hasContentColumn()</code> returns <code>false</code>) and nothing is saved against it when the order is saved.</li><li><strong>Not translatable.</strong> The field uses <code>TRANSLATION_METHOD_NONE</code>, since there&#39;s nothing per-site to translate - the same recorded events show regardless of site.</li><li><strong>One per layout is enough.</strong> Since the field has no settings and always shows the same order-wide data, adding it more than once to the same layout just repeats the same content.</li></ul><h2 id="empty-error-states" tabindex="-1">Empty &amp; Error States <a class="header-anchor" href="#empty-error-states" aria-label="Permalink to “Empty &amp; Error States”">​</a></h2><p>The field checks a few things before it renders anything, and shows a plain note instead of a section if a check fails. These are checked in order, so the first matching condition wins:</p><table tabindex="0"><thead><tr><th>Condition</th><th>What shows</th></tr></thead><tbody><tr><td>Craft Commerce isn&#39;t installed</td><td>&quot;Craft Commerce must be installed to use this field.&quot;</td></tr><tr><td>No element to render against at all</td><td>&quot;This field can only be used with saved orders.&quot;</td></tr><tr><td>The field is attached to something other than a Commerce order</td><td>&quot;This field can only be added to Commerce Order elements.&quot; (shown as a warning)</td></tr><tr><td>The order exists but hasn&#39;t been saved yet (no ID)</td><td>&quot;Order lifecycle events will appear after the order is saved.&quot;</td></tr><tr><td>The order is saved but has no recorded events yet</td><td>&quot;No Order lifecycle events yet - Events will be recorded as customers interact with this order.&quot;</td></tr></tbody></table><p>The last row is the one exception - it isn&#39;t a guard clause in the field class itself, but the template&#39;s own empty state once the field has everything it needs to render.</p><h2 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to “Technical Details”">​</a></h2><ul><li><strong>Class</strong>: <code>johnhenry\\orderlifecycle\\fields\\OrderLifecycleField</code></li><li><strong>Icon</strong>: <code>clock</code></li><li><strong>Display name</strong>: &quot;Order Lifecycle Events&quot;</li><li>Data is computed fresh on every page load by <code>OrderLifecycleLogger::getTimelineForOrder()</code> and <code>getLogsForOrder()</code> - nothing about the rendered field (summary cards, diffs, filtering) is cached or stored separately from the underlying <code>orderlifecycle_logs</code> table</li><li>The field template registers <code>OrderLifecycleAsset</code>, the plugin&#39;s CP asset bundle, which is what powers the filter pills, sort toggle, and AI Insights button client-side</li></ul><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><a href="/order-lifecycle/guide/installation.html">Installation</a> - First-time setup, including creating and adding this field</li><li><a href="/order-lifecycle/guide/timeline-view.html">Timeline View</a> - The event timeline section in detail</li><li><a href="/order-lifecycle/guide/statistics.html">Statistics</a> - The summary cards and dashboard-level stats</li><li><a href="/order-lifecycle/guide/ai-insights.html">AI Insights</a> - The Order analysis card in detail</li><li><a href="/order-lifecycle/guide/configuration.html">Configuration</a> - Plugin-wide settings that affect what this field shows</li></ul>',20))])}const T=a(h,[["render",g]]);export{b as __pageData,T as default};
